#ifndef ELECTRON_MBT_LINUX_CONTROL_FRAME_H
#define ELECTRON_MBT_LINUX_CONTROL_FRAME_H

#include <stddef.h>
#include <stdint.h>

/*
 * The Linux host accepts only the canonical frame generated by
 * native/nodeless/host_client.c. Parsing the JSON is not enough: duplicate
 * top-level identity keys and trailing members must never overwrite the
 * session/request/window/generation that the transport validated.
 */
typedef struct {
  char session[33];
  char operation[129];
  int64_t request;
  int64_t window;
  int64_t generation;
  size_t payload_offset;
  size_t payload_length;
} EbtControlFrame;

/* Return 1 on success, 0 on any malformed or non-canonical frame. */
int ebt_control_frame_validate(const char *data, size_t length,
                               EbtControlFrame *out);

#endif
